{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the edge of the ruined city.",
      "visual_description": "A windswept ridge overlooking a shattered skyline of broken spires; ink-stained maps unfurl across a stone.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "Oracle Lamp warns of the city's temptations.",
      "visual_description": "A single glowing eye flickers inside an oil lamp's flame, casting long warnings on cracked cobblestones.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Glass Diver arrives through a cracked window.",
      "visual_description": "A figure in a clear diving helmet steps from a fractured pane, coat shimmering with reflected city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox scouts the castle gates.",
      "visual_description": "A small clockwork fox crouches behind toppled banners, blue glass eyes scanning iron-bound doors.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "An armored patrol stomps past in silence.",
      "visual_description": "Empty suits of plate metal march on their own beneath torn royal banners; the fox hides in a gutter.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Mara charts a path past the cursed tower.",
      "visual_description": "A leaning tower drips violet smoke; Mara presses a brass compass to a map fluttering in unnatural wind.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The Sleeping Tax Collector blocks an alley, snoring.",
      "visual_description": "A round official slumps against a wall, ledger as pillow, stamped papers fluttering from his sleeves.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "Glass Diver slips through a tall mirror in the plaza.",
      "visual_description": "Ripples spread across an enormous mirror as the coated figure dives into it like water.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Rumors of a beast in the sky pass overhead.",
      "visual_description": "A great winged shadow ripples across rooftops; Tin Fox's tail-key freezes mid-tick.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Frightened townsfolk peek from shuttered windows.",
      "visual_description": "Pale faces watch from cracked shutters as Mara signals silence with one inked finger.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Oracle Lamp reveals a magic door beneath royal banners.",
      "visual_description": "Glowing runes pulse along a stone arch hidden behind drooping crimson cloth.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The Sleeping Tax Collector mumbles a password in his sleep.",
      "visual_description": "The dozing official drools as the runes brighten in rhythm with his snores; Mara leans in, listening.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The magic door swings open into a hall of broken glass.",
      "visual_description": "A vast chamber of shattered chandeliers and reflective shards stretches before the team.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Glass Diver finds the captive trapped in a tall window.",
      "visual_description": "A small figure presses against the inside of stained glass; the Diver lays a gloved hand to its surface.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Tin Fox triggers the alarm bells of the cursed tower.",
      "visual_description": "Bells crack and toll above; the clockwork fox sprints across tiles trailing sparks from its tail.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The team races toward the river bridge.",
      "visual_description": "Empty armor floods the streets behind them; Mara leads with her compass flaring blue.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "Oracle Lamp lights the way across the crumbling bridge.",
      "visual_description": "A long stone span over black water, lit by the lamp's single eye; the Sleeping Tax Collector is dragged behind on his ledger like a sled.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, the rescuers look back at the ruined city.",
      "visual_description": "Dawn breaks over fallen spires; the team stands on a grassy bank, the rescued figure wrapped in Mara's coat.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

